mapper.delete:
delete from sys_episode_like
where user_id = #{userId}
  and episode_id = #{episodeId}

mapper.update:
update sys_episode
set like_count = like_count + 1
where episode_id = #{episodeId}

update sys_episode
set like_count = greatest(like_count - 1, 0)
where episode_id = #{episodeId}

mapper.select:
select like_count
from sys_episode
where episode_id = #{episodeId}
